<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/app/more" /></ion-buttons><ion-title>Goat tracking</ion-title></ion-toolbar></ion-header><ion-content><main class="page-wrap">
  <div class="info-note"><ion-icon :icon="radioOutline" /><p>BLE indicates proximity to a receiver, not exact GPS coordinates.</p></div><StatePanel v-if="loading" loading title="Locating tagged goats" message="Reading the latest BLE receiver observations." /><StatePanel v-else-if="error" tone="danger" title="Tracking unavailable" :message="error" :retry="load" />
  <section v-else class="tracking-list"><article v-for="item in snapshot?.goats" :key="item.beacon.id"><div class="proximity-ring" :class="item.status"><ion-icon :icon="radioOutline" /></div><div><span>{{ item.goat.goat_id }}</span><h2>{{ item.goat.name || 'Unnamed goat' }}</h2><p>{{ item.receiver?.location || 'No receiver' }} · {{ item.proximity_display }}</p><small>Last seen {{ relativeTime(item.last_seen) }}</small></div><b :class="item.status">{{ item.status_display }}</b></article></section>
</main></ion-content></ion-page></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { IonBackButton, IonButtons, IonContent, IonHeader, IonIcon, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import { radioOutline } from 'ionicons/icons'; import StatePanel from '@/components/StatePanel.vue'; import { trackingService, type TrackingSnapshot } from '@/services/tracking.service'; import { relativeTime } from '@/utils/format';
const snapshot = ref<TrackingSnapshot>(); const loading = ref(true); const error = ref(''); async function load() { loading.value = true; error.value = ''; try { snapshot.value = await trackingService.get(); } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to retrieve tracking.'; } finally { loading.value = false; } } onMounted(load);
</script>
